import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.DPTp4bo7.js";const u=JSON.parse('{"title":"优先输入/输出/汇入理论","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/input-output-merge-priority-theory"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/input-output-merge-priority-theory"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/input-output-merge-priority-theory"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/input-output-merge-priority-theory"}]]},"headers":[],"relativePath":"zh/input-output-merge-priority-theory.md","filePath":"zh/page-AA41FJVehHzDTC97GcFV5F.md"}'),r={name:"zh/input-output-merge-priority-theory.md"};function o(n,e,d,c,p,l){return i(),s("div",null,[...e[0]||(e[0]=[t('<div class="logistics-content"><span class="logistics-source-anchor" id="优先输入-输出-汇入理论" aria-hidden="true"></span><h1 id="优先输入-输出-汇入理论" tabindex="-1">优先输入/输出/汇入理论 <a class="header-anchor" href="#优先输入-输出-汇入理论" aria-label="Permalink to &quot;优先输入/输出/汇入理论&quot;">​</a></h1><blockquote><p>源页面 ID：<code>AA41FJVehHzDTC97GcFV5F</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AA41FJVehHzDTC97GcFV5F" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>本页面主要面向不了解基本的优先输入输出而难以直接阅读<a href="/endfield-skydoc/zh/introduction-to-analyzing-endfield-logistics-bugs">终末地物流bug分析导论</a>的读者</p><p><span id="source-block-LStqO3ihrJjZA2Uyti9bzr"></span></p><span class="logistics-source-anchor" id="优先输出-协议箱-汇流器-多口暗管出口-汇流器" aria-hidden="true"></span><h2 id="优先输出-协议箱-汇流器-多口暗管出口-汇流器" tabindex="-1">优先输出 协议箱-汇流器/多口暗管出口-汇流器 <a class="header-anchor" href="#优先输出-协议箱-汇流器-多口暗管出口-汇流器" aria-label="Permalink to &quot;优先输出 协议箱-汇流器/多口暗管出口-汇流器&quot;">​</a></h2><p><img src="/endfield-skydoc/logistics/src/assets/images/img-158b774bfb7274dc.q90-a0e442d04c7e3c73.webp" alt="优先输入/输出/汇入理论"></p><p>简单来说，当协议箱/多口暗管出口和汇流器紧贴放置时，产生输出优先级。以上图为例，我们数出两路上传送带（管道）和物流件（管道件）数量（即阻尼），少的一路优先输出，多的一路次优先。</p><p><span class="mark-grey">特别的，对于固体来说，不同于液气，协议箱可以直接用封装机粉碎机等等有多出口机器来代替，或者说可以直接在其出口放置紧贴的汇流器以实现优先输出。</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c5624772107f24fe.gif" alt="优先输入/输出/汇入理论"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fe0d488ade871fd6.gif" alt="优先输入/输出/汇入理论"></p><p>更复杂的情况请移步<a href="/endfield-skydoc/zh/introduction-to-analyzing-endfield-logistics-bugs">终末地物流bug分析导论</a></p><p><span id="source-block-YaKEdAbnDnMx5Vv6e3oH6j"></span></p><span class="logistics-source-anchor" id="优先汇入-分流器-汇流器" aria-hidden="true"></span><h2 id="优先汇入-分流器-汇流器" tabindex="-1">优先汇入 分流器-汇流器 <a class="header-anchor" href="#优先汇入-分流器-汇流器" aria-label="Permalink to &quot;优先汇入 分流器-汇流器&quot;">​</a></h2><p>简单来说如果存在分流器出口紧贴汇流器入口时，汇流器的汇入产生优先级，其上游先放的优先，如果是先放的是非分流器的话会与后放的其他非分流器轮询。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-82eba631c9f66e78.gif" alt="优先输入/输出/汇入理论"></p><p><span class="mark-grey">更详尽的优先级与放置顺序的关系：对于分流器之间，先放置的分流器向汇流器的输入优先于后放置的；对于管道、储液/气罐、暗管出口、汇流器之间，优先级一致且以最先放置的为准；对于分流器和管道、储液/气罐、暗管出口、汇流器之间，先放置的一方向汇流器的输入优先于后放置的（注意管道等一方的优先级将相同，比如对一汇流器先连管道A再连分流器B再连管道C，优先级为A=C&gt;B）</span></p><p>机器与分流器与管道等之间的关系尚未完全厘清，主要是反应池令人不解，请以实际情况为准。</p><p>更复杂的情况请移步：<a href="/endfield-skydoc/zh/introduction-to-analyzing-endfield-logistics-bugs">终末地物流bug分析导论</a></p><p><span id="source-block-SJwMhKtD8ELVC0QucYr9nJ"></span></p><span class="logistics-source-anchor" id="通过正常轮询达成的输出-输入优先" aria-hidden="true"></span><h2 id="通过正常轮询达成的输出-输入优先" tabindex="-1">通过正常轮询达成的输出/输入优先 <a class="header-anchor" href="#通过正常轮询达成的输出-输入优先" aria-label="Permalink to &quot;通过正常轮询达成的输出/输入优先&quot;">​</a></h2><p>输出优先：多口暗管出口A正在输出120/min的息壤气，两个口分别连接消耗30/min息壤气的暗管入口B和消耗120/min息壤气的暗管入口C，可以得到B的消耗被优先供应满的结论。严格地说，只要暗管入口B/C的消耗量小于A流量的1/2（多口暗管在两个口都不堵时轮询输出，即足够长时间中两口输出相等，所以这里是1/2）就能保证供应充足（可以说是广义上的优先输出）</p><p>输入优先：多口暗管入口A正在消耗120/min的息壤气，两个口分别连接输出30/min息壤气的暗管出口B和输出120/min息壤气的暗管出口C，可以得到B的输出被优先消耗完的结论。严格地说，只要暗管入口B/C的输入量小于A流量的1/2（多口暗管在两个口都阻塞时轮询输入，即足够长时间中两口输入相等，所以这里是1/2）就能保证消耗完全（可以说是广义上的优先输入）</p><p>更系统的解释我在这里引用kokobird的<a href="/endfield-skydoc/zh/2-5-is-a-stash-not-just-a-special-splitter">2.5 箱子不就是特殊的分流器吗？（核心内容⭐）</a></p><p><span id="source-block-cSE6qgeFTPC10fGIVcuoTG"></span></p><span class="logistics-source-anchor" id="四卡一-迟滞输出-造成的输入优先级损坏" aria-hidden="true"></span><h2 id="四卡一-迟滞输出-造成的输入优先级损坏" tabindex="-1">四卡一（迟滞输出）造成的输入优先级损坏 <a class="header-anchor" href="#四卡一-迟滞输出-造成的输入优先级损坏" aria-label="Permalink to &quot;四卡一（迟滞输出）造成的输入优先级损坏&quot;">​</a></h2><p>优先级可能会因为分流器四卡一（迟滞输出）使得优先级损坏为不完全的优先级，如果发现优先级损坏且上游阻塞时输出方式为优先一方进2液体而次优先一方输出1液体（而不是正常轮询的你进1我进1）则大概率发生四卡一，简单的修复方法有二：（正在验证方法充分性）</p><p>详细内容请移步<a href="/endfield-skydoc/zh/introduction-to-analyzing-endfield-logistics-bugs">终末地物流bug分析导论</a></p></div>',1)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
